window.AUDIO_DATA={"tracks": [{"id": "B2_U07_T7.1_SHORT_S01_v01", "audioId": "B2_U07_T7.1_SHORT_S01_v01", "title": "Book 2 · Unit 7 · H1 · 听力材料 1", "subtitle": "H1 · S01", "duration": 91.769229, "cues": [{"start": 0.23, "end": 3.96, "text": "Unit 7, 7.1", "coverage": 1.0}, {"start": 5.24, "end": 6.43, "text": "Student presenter: Hello, everyone.", "coverage": 0.5}, {"start": 7.0, "end": 19.0, "text": "So, in this presentation I’d like to discuss the designers of some everyday objects: Arne Jacobsen, Sir James Dyson and Sir Jonathan Ive.", "coverage": 0.833}, {"start": 21.48, "end": 29.37, "text": "These people designed simple things that have changed our lives and how we do everyday things.", "coverage": 1.0}, {"start": 30.36, "end": 40.4, "text": "Today we are going to think about these inventors and designers, their achievements and how their inventions and designs have helped us.", "coverage": 0.955}, {"start": 40.96, "end": 48.18, "text": "I would like to start with Arne Jacobsen, who was born in Denmark in 1902.", "coverage": 0.867}, {"start": 48.6, "end": 56.88, "text": "When he was a child, he loved to paint, but his father thought being an artist wasn’t a good career.", "coverage": 1.0}, {"start": 57.41, "end": 64.28, "text": "So, Jacobsen became a designer of many things, including buildings and furniture.", "coverage": 0.917}, {"start": 65.0, "end": 70.99, "text": "For example, here is a chair he designed in 1958.", "coverage": 1.0}, {"start": 71.17, "end": 73.38, "text": "It’s called the ‘Egg Chair’.", "coverage": 1.0}, {"start": 74.16, "end": 76.92, "text": "Have any of you seen this kind of chair before?", "coverage": 1.0}, {"start": 77.29, "end": 77.58, "text": "Razia: I have.", "coverage": 0.667}, {"start": 78.98, "end": 81.89, "text": "Did they call it the Egg Chair because of its shape?", "coverage": 1.0}, {"start": 82.2, "end": 84.4, "text": "It’s an interesting design.", "coverage": 1.0}, {"start": 84.95, "end": 87.32, "text": "Student presenter: Yes, you have a good point.", "coverage": 0.75}, {"start": 87.55, "end": 91.08, "text": "I think it was called that because of the egg-like shape.", "coverage": 1.0}]}, {"id": "B2_U07_T7.1_SHORT_S02_v01", "audioId": "B2_U07_T7.1_SHORT_S02_v01", "title": "Book 2 · Unit 7 · H1 · 听力材料 2", "subtitle": "H1 · S02", "duration": 82.508821, "cues": [{"start": 1.1, "end": 4.84, "text": "Student presenter: Nowadays, we still see Jacobsen’s designs around us.", "coverage": 0.636}, {"start": 5.37, "end": 10.67, "text": "When you look at the chair design, can you guess what Jacobsen was like as a person?", "coverage": 0.941}, {"start": 11.32, "end": 14.64, "text": "Razia: His chair looks like a simple, neat design.", "coverage": 0.889}, {"start": 15.03, "end": 19.61, "text": "So maybe he liked simple and neat things and not complicated things.", "coverage": 1.0}, {"start": 20.41, "end": 21.72, "text": "Student presenter: Actually, that’s right.", "coverage": 0.667}, {"start": 22.0, "end": 23.23, "text": "He did.", "coverage": 1.0}, {"start": 24.3, "end": 33.0, "text": "For example, when he was growing up, he painted his room white because he didn’t like all the flowers on the wallpaper he had.", "coverage": 1.0}, {"start": 33.03, "end": 37.58, "text": "And as an adult, he worked hard to make his designs perfect.", "coverage": 1.0}, {"start": 38.03, "end": 44.62, "text": "In fact, he often kept his workers at work until late, trying to make things better.", "coverage": 1.0}, {"start": 45.03, "end": 51.5, "text": "But even though he worked hard, Jacobsen liked to joke and do funny things.", "coverage": 0.929}, {"start": 52.3, "end": 62.73, "text": "For instance, as a child he liked to play jokes on others and as an adult he once wore a melon for a hat when someone dared him to.", "coverage": 0.966}, {"start": 63.03, "end": 70.03, "text": "He also liked working on his own projects in his free time and found painting to be relaxing.", "coverage": 1.0}, {"start": 71.41, "end": 75.6, "text": "These days, Jacobsen is famous for his modern, simple designs.", "coverage": 0.9}, {"start": 76.03, "end": 81.68, "text": "His work showed that he thought about the purpose that his designs would serve for people.", "coverage": 1.0}]}, {"id": "B2_U07_T7.1_SHORT_S03_v01", "audioId": "B2_U07_T7.1_SHORT_S03_v01", "title": "Book 2 · Unit 7 · H1 · 听力材料 3", "subtitle": "H1 · S03", "duration": 76.996984, "cues": [{"start": 0.5, "end": 5.11, "text": "Student presenter: Next, I’d like to talk about an inventor, James Dyson.", "coverage": 0.769}, {"start": 6.16, "end": 12.42, "text": "Can anyone think of something you often use that might have his last name, Dyson, on it?", "coverage": 0.941}, {"start": 12.87, "end": 15.25, "text": "Razia: I know, a vacuum cleaner!", "coverage": 0.833}, {"start": 15.51, "end": 15.85, "text": "Ebru: Or a hand dryer?", "coverage": 0.4}, {"start": 17.1, "end": 19.57, "text": "Student presenter: Both of those things are correct.", "coverage": 0.75}, {"start": 20.25, "end": 24.62, "text": "Dyson’s designs and inventions are made to solve problems.", "coverage": 0.9}, {"start": 25.26, "end": 31.92, "text": "His ideas come because he sees things that could work better, like the vacuum cleaner and hand dryer.", "coverage": 0.944}, {"start": 32.71, "end": 34.96, "text": "But how did he start?", "coverage": 1.0}, {"start": 35.51, "end": 40.19, "text": "Well, Dyson was born in England in 1947.", "coverage": 0.875}, {"start": 40.51, "end": 43.95, "text": "His father died when he was only nine.", "coverage": 1.0}, {"start": 44.48, "end": 49.43, "text": "As a result, Dyson ended up becoming someone who never gave up.", "coverage": 0.917}, {"start": 49.94, "end": 53.91, "text": "He studied Art and Design before he studied Engineering.", "coverage": 1.0}, {"start": 54.26, "end": 61.03, "text": "When he saw something that didn’t work well, he got frustrated and worked to improve it.", "coverage": 1.0}, {"start": 61.4, "end": 67.06, "text": "For example, his first invention was a wheelbarrow with a ball for a wheel.", "coverage": 0.929}, {"start": 67.3, "end": 73.02, "text": "This made it easier to carry heavy things in the garden and over rough ground.", "coverage": 1.0}, {"start": 73.35, "end": 76.07, "text": "It was an interesting new use for a ball.", "coverage": 1.0}]}, {"id": "B2_U07_T7.1_SHORT_S04_v01", "audioId": "B2_U07_T7.1_SHORT_S04_v01", "title": "Book 2 · Unit 7 · H1 · 听力材料 4", "subtitle": "H1 · S04", "duration": 58.032086, "cues": [{"start": 0.4, "end": 6.66, "text": "Student presenter: Also, even though he changed subjects, he was still interested in art as well as designing.", "coverage": 0.889}, {"start": 8.06, "end": 9.41, "text": "Take a look at this photo.", "coverage": 1.0}, {"start": 9.71, "end": 10.52, "text": "What do you see?", "coverage": 1.0}, {"start": 10.87, "end": 17.2, "text": "Ebru: It looks like a waterfall made from glass and water, with the water running up instead of falling down.", "coverage": 0.95}, {"start": 17.55, "end": 18.37, "text": "That’s surprising.", "coverage": 1.0}, {"start": 19.25, "end": 19.68, "text": "Student presenter: That’s right.", "coverage": 0.6}, {"start": 20.69, "end": 26.68, "text": "This was a piece of art that Dyson made in 2003, called Wrong Garden.", "coverage": 0.929}, {"start": 27.19, "end": 28.79, "text": "It tricks the eye.", "coverage": 1.0}, {"start": 29.53, "end": 34.38, "text": "This shows Dyson’s love of good design as well as being an inventor.", "coverage": 0.929}, {"start": 35.16, "end": 37.14, "text": "Dyson is still inventing new things.", "coverage": 0.667}, {"start": 37.36, "end": 48.63, "text": "But he is also interested in supporting education for students and gives money to schools to help students study so they might become inventors, too.", "coverage": 0.96}, {"start": 49.09, "end": 57.56, "text": "He has even donated money to the University of Cambridge to support students and research there, with a focus on technology.", "coverage": 1.0}]}, {"id": "B2_U07_T7.1_SHORT_S05_v01", "audioId": "B2_U07_T7.1_SHORT_S05_v01", "title": "Book 2 · Unit 7 · H1 · 听力材料 5", "subtitle": "H1 · S05", "duration": 52.356644, "cues": [{"start": 0.34, "end": 3.45, "text": "Student presenter: Now, I have one last picture to show you.", "coverage": 0.818}, {"start": 3.8, "end": 6.82, "text": "It’s a phone with a special design.", "coverage": 1.0}, {"start": 7.48, "end": 9.65, "text": "It’s called the iPhone.", "coverage": 1.0}, {"start": 10.0, "end": 12.26, "text": "I think a lot of us know about this phone.", "coverage": 1.0}, {"start": 12.6, "end": 16.07, "text": "It was designed by Sir Jonathan Ive for Apple.", "coverage": 0.889}, {"start": 16.8, "end": 23.82, "text": "He is responsible for a lot of Apple’s product designs, which are simple, clean and slim.", "coverage": 1.0}, {"start": 24.55, "end": 31.65, "text": "Ive has won a lot of awards for his Apple designs, and you can see a lot of his work in museums, too.", "coverage": 0.957}, {"start": 32.0, "end": 40.26, "text": "He is from London, and he was made a Knight Commander of the British Empire in 2012 for his design work.", "coverage": 1.0}, {"start": 40.6, "end": 43.88, "text": "He is known as being hard-working and creative.", "coverage": 1.0}, {"start": 44.2, "end": 50.65, "text": "I think that his designs will continue to influence the way we live and work for a long time!", "coverage": 1.0}]}], "audio": {"B2_U07_T7.1_SHORT_S01_v01": "../assets/media/8b16f1befa2453facf29d5ac265cf845aa9552c4d201741418c2ff8680aa91ec.mp3", "B2_U07_T7.1_SHORT_S02_v01": "../assets/media/aa2336ec3808cdae8d48abbd5210b855f4fc6a45dbf20f23e558b0fc825980bf.mp3", "B2_U07_T7.1_SHORT_S03_v01": "../assets/media/2eee1c965bcffde997cb83b60effa72d9a31048495347a2f1c18e8f905e12dc2.mp3", "B2_U07_T7.1_SHORT_S04_v01": "../assets/media/5b99c5be0ff02dc0b432d1e178b1da4d22bd997409f66e46ed4f21e3c5acf131.mp3", "B2_U07_T7.1_SHORT_S05_v01": "../assets/media/a2417acfbc5c06eb04b6fa622d101ae0cac93e42ba9032498bad6920648b787b.mp3"}};